<section class="section projects-section" id="projects"><div class="container"><div class="section-head"><div><span class="eyebrow"><span class="eyebrow-line"></span> نمونه‌کارهای برتر / OUR PROJECTS</span><h2>پروژه‌های <em>نورپردازی شهری</em></h2><p>هر پروژه، روایتی از هنر، مهندسی و نور است که هویت بصری شهر را دگرگون می‌کند.</p></div><a class="text-link" href="<?php echo esc_url( es_projects_url() ); ?>">آرشیو تمام پروژه‌ها <span aria-hidden="true">↖</span></a></div>
<div class="projects-grid"><?php $projects = new WP_Query( array( 'post_type' => 'project', 'posts_per_page' => 3, 'no_found_rows' => true ) ); if ( $projects->have_posts() ) : while ( $projects->have_posts() ) : $projects->the_post(); get_template_part( 'template-parts/cards/project' ); endwhile; wp_reset_postdata(); else : $samples = array( array( 'تونل نوری', 'light-tunnel.jpg', 'مسیرهای عبوری با جلوه‌ای جادویی؛ از بوستان‌ها تا جشنواره‌های شهری' ), array( 'گوی نورانی', 'light-sphere.jpg', 'کره‌های درخشان؛ نقطه کانونی میادین و فضاهای باز شهری' ), array( 'درخت نوری', 'light-tree.jpg', 'طراحی و ساخت المان‌های نوری با هویتی ماندگار' ) ); foreach ( $samples as $i => $item ) : ?><a class="project-card" href="<?php echo esc_url( es_projects_url() ); ?>"><div class="project-card__image"><img loading="lazy" src="<?php echo esc_url( es_asset( 'images/' . $item[1] ) ); ?>" alt="<?php echo esc_attr( $item[0] ); ?>"><span class="project-card__arrow">↗</span></div><div class="project-card__info"><span class="project-card__meta">۰<?php echo esc_html( $i + 1 ); ?> / نورپردازی شهری</span><h3><?php echo esc_html( $item[0] ); ?></h3><p><?php echo esc_html( $item[2] ); ?></p></div></a><?php endforeach; endif; ?></div></div></section>
